def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = [0, 0]  # stem above, stem below

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            component = set()
            while stack:
                cr, cc = stack.pop()
                component.add((cr, cc))
                for nr, nc in ((cr - 1, cc), (cr + 1, cc),
                               (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w
                            and grid[nr][nc] == 2
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            stem_above = False
            stem_below = False
            for cr, cc in component:
                if all((cr, cc + offset) in component for offset in (-1, 0, 1)):
                    if (cr - 1, cc) in component:
                        stem_above = True
                    if (cr + 1, cc) in component:
                        stem_below = True

            if stem_above:
                counts[0] += 1
            elif stem_below:
                counts[1] += 1

    out = [[0] * 6 for _ in range(3)]
    slots = [(0, 0), (2, 0), (0, 2), (2, 2)]
    for color, count, start_col in ((3, counts[0], 0), (1, counts[1], 3)):
        for rr, cc in slots[:count]:
            out[rr][start_col + cc] = color
    return out
